WITH ranked AS (SELECT id, store_id, product_id, quantity, last_restock FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id, store_id ORDER BY quantity DESC NULLS LAST, id) AS rank_in_group FROM inventory) ranked WHERE rank_in_group = 1) SELECT s.id, s.store_id, s.product_id, s.quantity, (SELECT AVG(i2.quantity) FROM inventory i2 WHERE i2.store_id = s.store_id) AS avg_inventory_quantity FROM ranked s;
